ch04-play-borrow-fix.solution_code:
fn check_status(sat: &String) -> &'static str {
    if sat.is_empty() { "unknown" } else { "ok" }
}

fn log_contact(sat: &mut String) {
    sat.push_str(" (contacted)");
}

fn main() {
    let mut sat_a = String::from("sat-a");
    println!("{sat_a}: {}", check_status(&sat_a));
    println!("{sat_a}: {}", check_status(&sat_a));
    log_contact(&mut sat_a);
    println!("{sat_a}");
}

