ch04-play-cubesat.solution_code:
fn check_status(sat: String) -> (String, &'static str) {
    let status = if sat.is_empty() { "unknown" } else { "ok" };
    (sat, status)
}

fn main() {
    let sat_a = String::from("sat-a");
    let (sat_a, status) = check_status(sat_a);
    println!("{sat_a}: {status}");
    let (sat_a, status) = check_status(sat_a);
    println!("{sat_a}: {status}");
}

ch04-play-last-word.solution_code:
fn last_word(s: &str) -> &str {
    match s.rfind(' ') {
        Some(i) => &s[i + 1..],
        None => s,
    }
}

fn main() {
    println!("{}", last_word("hello world"));
    println!("{}", last_word("Ferris"));
    let owned = String::from("Ferris the crab");
    println!("{}", last_word(&owned));
}

ch05-play-counter.solution_code:
struct Counter {
    count: u32,
}

impl Counter {
    fn new() -> Self {
        Self { count: 0 }
    }

    fn increment(&mut self) {
        self.count += 1;
    }

    fn add(&mut self, n: u32) {
        self.count += n;
    }

    fn get(&self) -> u32 {
        self.count
    }
}

fn main() {
    let mut c = Counter::new();
    c.increment();
    c.add(2);
    println!("count: {}", c.get());
}

ch05-play-rect.solution_code:
#[derive(Debug)]
struct Rectangle {
    width: u32,
    height: u32,
}

fn area(r: &Rectangle) -> u32 {
    r.width * r.height
}

fn perimeter(r: &Rectangle) -> u32 {
    2 * (r.width + r.height)
}

fn is_square(r: &Rectangle) -> bool {
    r.width == r.height
}

fn main() {
    let shapes = [Rectangle { width: 30, height: 50 }, Rectangle { width: 20, height: 20 }];
    for r in &shapes {
        println!("{r:?}: area {}, perimeter {}, square {}", area(r), perimeter(r), is_square(r));
    }
}

